script:
test("partial hour rounds up to the next whole hour", function () {
  var actual = code.billableObservationHours({
    admission: "2026-01-10 08:00",
    discharge: "2026-01-10 10:01"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 121,
    roundedHours: 3,
    billableHours: 3,
    flags: []
  });
});

test("exact hour stays unchanged at the two hour boundary", function () {
  var actual = code.billableObservationHours({
    admission: "2026-01-10 08:00",
    discharge: "2026-01-10 10:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 120,
    roundedHours: 2,
    billableHours: 2,
    flags: []
  });
});

test("one minute below an exact hour rounds up", function () {
  var actual = code.billableObservationHours({
    admission: "2026-01-10 08:00",
    discharge: "2026-01-10 09:59"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 119,
    roundedHours: 2,
    billableHours: 2,
    flags: []
  });
});

test("zero elapsed time on the first of January has empty flags", function () {
  var actual = code.billableObservationHours({
    admission: "2026-01-01 00:00",
    discharge: "2026-01-01 00:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 0,
    roundedHours: 0,
    billableHours: 0,
    flags: []
  });
});

test("one minute across leap day rounds up to one hour", function () {
  var actual = code.billableObservationHours({
    admission: "2024-02-29 23:59",
    discharge: "2024-03-01 00:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 1,
    roundedHours: 1,
    billableHours: 1,
    flags: []
  });
});

test("exactly one hour from the last day of the year into the next", function () {
  var actual = code.billableObservationHours({
    admission: "2025-12-31 23:00",
    discharge: "2026-01-01 00:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 60,
    roundedHours: 1,
    billableHours: 1,
    flags: []
  });
});

test("spring forward night is billed as real time not wall clock", function () {
  var actual = code.billableObservationHours({
    admission: "2026-03-07 22:00",
    discharge: "2026-03-08 22:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 1380,
    roundedHours: 23,
    billableHours: 23,
    flags: []
  });
});

test("fall back night is billed as real time not wall clock", function () {
  var actual = code.billableObservationHours({
    admission: "2026-10-31 22:00",
    discharge: "2026-11-01 22:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 1500,
    roundedHours: 25,
    billableHours: 25,
    flags: []
  });
});

test("a stay far above forty eight hours is capped", function () {
  var actual = code.billableObservationHours({
    admission: "2026-01-10 08:00",
    discharge: "2026-01-13 08:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 4320,
    roundedHours: 72,
    billableHours: 48,
    flags: []
  });
});

test("exactly forty eight hours is billed as forty eight", function () {
  var actual = code.billableObservationHours({
    admission: "2026-04-30 00:00",
    discharge: "2026-05-02 00:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 2880,
    roundedHours: 48,
    billableHours: 48,
    flags: []
  });
});

test("one hour below the cap is not capped", function () {
  var actual = code.billableObservationHours({
    admission: "2026-04-30 00:00",
    discharge: "2026-05-01 23:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 2820,
    roundedHours: 47,
    billableHours: 47,
    flags: []
  });
});

test("one minute above forty eight hours rounds up then caps at forty eight", function () {
  var actual = code.billableObservationHours({
    admission: "2026-04-30 00:00",
    discharge: "2026-05-02 00:01"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 2881,
    roundedHours: 49,
    billableHours: 48,
    flags: []
  });
});

test("ambiguous local time on admission is flagged and hours are not computed", function () {
  var actual = code.billableObservationHours({
    admission: "2026-11-01 01:30",
    discharge: "2026-11-01 03:00"
  });
  assert.equal(actual.status, "ambiguous");
  assert.equal(actual.elapsedMinutes, null);
  assert.equal(actual.roundedHours, null);
  assert.equal(actual.billableHours, null);
  assert.equal(actual.flags.length, 1);
  assert.match(actual.flags[0], /admission/i);
});

test("nonexistent local time on discharge is flagged and hours are not computed", function () {
  var actual = code.billableObservationHours({
    admission: "2026-03-08 01:30",
    discharge: "2026-03-08 02:30"
  });
  assert.equal(actual.status, "nonexistent");
  assert.equal(actual.elapsedMinutes, null);
  assert.equal(actual.roundedHours, null);
  assert.equal(actual.billableHours, null);
  assert.equal(actual.flags.length, 1);
  assert.match(actual.flags[0], /discharge/i);
});

test("discharge earlier than admission is flagged invalid", function () {
  var actual = code.billableObservationHours({
    admission: "2026-01-10 10:01",
    discharge: "2026-01-10 08:00"
  });
  assert.equal(actual.status, "invalid");
  assert.equal(actual.elapsedMinutes, null);
  assert.equal(actual.roundedHours, null);
  assert.equal(actual.billableHours, null);
  assert.equal(actual.flags.length, 1);
  assert.match(actual.flags[0], /discharge/i);
});

test("times just outside the repeated hour use real elapsed time", function () {
  var actual = code.billableObservationHours({
    admission: "2026-11-01 00:59",
    discharge: "2026-11-01 02:00"
  });
  assert.deepEqual(actual, {
    status: "ok",
    elapsedMinutes: 121,
    roundedHours: 3,
    billableHours: 3,
    flags: []
  });
});
